        if e==Eall:
            if f==0: return ('inf',s,None)
            return ('nan',s,(f>>(fbits-1))&1)
        if e==0: return ('fin',s,Fraction(f)*(Fraction(2)**(1-bias-fbits)))
        return ('fin',s,Fraction(F+f)*(Fraction(2)**(e-bias-fbits)))
    def enc_zero(s): return s<<(ebits+fbits)
    def enc_inf(s): return (s<<(ebits+fbits))|(Eall<<fbits)
    nan_bits=(Eall<<fbits)|(1<<(fbits-1))
    def floor_log2(x):  # x positive Fraction
        L=x.numerator.bit_length()-x.denominator.bit_length()
        if x < Fraction(2)**L: L-=1
        return L
    def solve(mode,pairs_vals):
        saw_nan=False; invalid=False; infs=set(); prods=[]
        for va,vb in pairs_vals:
            a=decode(va); b=decode(vb)
            an=a[0]=='nan'; bn=b[0]=='nan'
            if an:
                saw_nan=True
                if not a[2]: invalid=True
            if bn:
                saw_nan=True
                if not b[2]: invalid=True
            if an or bn: continue
            if a[0]=='inf' or b[0]=='inf':
                z=(a[0]=='fin' and a[2]==0) or (b[0]=='fin' and b[2]==0)
                if z: invalid=True
                else: infs.add(a[1]^b[1])
                continue
            prods.append((a[1]^b[1], (a[2]*b[2])))
        if invalid or len(infs)==2:
            return nan_bits, {'invalid'}
        if saw_nan: return nan_bits,set()
        if infs:
            return enc_inf(next(iter(infs))),set()
        total=sum(((-1)**s)*v for s,v in prods)  # Fraction
        if total==0:
            s = 1 if (prods and all(v==0 and sgn==1 for sgn,v in prods) or mode=='RDN') else 0
            return enc_zero(s),set()
        s=1 if total<0 else 0
        x=abs(total)
        L=floor_log2(x)
        q=Fraction(2)**max(emin-fbits,L-fbits)
        r=x/q
        n=r.numerator//r.denominator
        frac=r-n
        half=Fraction(1,2)
        if mode=='RNE':
            if frac>half or (frac==half and n%2==1): n+=1
        elif mode=='RNA':
            if frac>=half: n+=1
        elif mode=='RUP':
            if frac>0 and s==0: n+=1
        elif mode=='RDN':
            if frac>0 and s==1: n+=1
        y=n*q
        if y>=Fraction(2)**(emax+1):
            flags={'overflow','inexact'}
            if mode in ('RNE','RNA') or (mode=='RUP' and s==0) or (mode=='RDN' and s==1):
                return enc_inf(s),flags
            return (s<<(ebits+fbits))|((Eall-1)<<fbits)|(F-1),flags
        flags=set()
        if y!=x:
            flags.add('inexact')
            if y<Fraction(2)**emin: flags.add('underflow')
        if y==0:
            return enc_zero(s),flags
        if y<Fraction(2)**emin:
            f=int(y/(Fraction(2)**(emin-fbits)))
            return (s<<(ebits+fbits))|f,flags
        L2=floor_log2(y)
        e_field=L2+bias
        sig=int(y/(Fraction(2)**(L2-fbits)))
        f=sig-F
        return (s<<(ebits+fbits))|(e_field<<fbits)|f,flags
    return solve
