            total += m << (E - E0)

    if total == 0:
        # exact zero
        if prods and all(m == 0 and s == 1 for s, m, _ in prods):
            s = 1
        elif mode == 'RDN':
            s = 1
        else:
            s = 0
        return {"bits": format(s << spos, 'x'), "flags": []}

    s = 1 if total < 0 else 0
    a = -total if s else total          # x = a * 2^E0, a > 0
    L = a.bit_length() - 1 + E0         # floor(log2(x))
    q_exp = emin - fbits
    if L - fbits > q_exp:
        q_exp = L - fbits
    shift = q_exp - E0
    if shift <= 0:
        n = a << (-shift)
        rem = 0
        half = 0
    else:
        n = a >> shift
        rem = a - (n << shift)
        half = 1 << (shift - 1)

    if rem:
        if mode == 'RNE':
            if rem > half or (rem == half and (n & 1)):
                n += 1
        elif mode == 'RNA':
            if rem >= half:
                n += 1
        elif mode == 'RUP':
            if s == 0:
                n += 1
        elif mode == 'RDN':
            if s == 1:
                n += 1
        # RTZ: truncate
        inexact = True
    else:
        inexact = False

    # y = n * 2^q_exp is the rounded magnitude
    if n and n.bit_length() - 1 + q_exp >= emax + 1:
        # overflow
        if mode == 'RNE' or mode == 'RNA' or (mode == 'RUP' and s == 0) or (mode == 'RDN' and s == 1):
            bits = (s << spos) | (Eall << fbits)             # signed infinity
        else:
            bits = (s << spos) | ((Eall - 1) << fbits) | fmask  # signed max finite
        return {"bits": format(bits, 'x'), "flags": ["overflow", "inexact"]}

    flags = []
    if inexact:
        flags.append('inexact')
        if n.bit_length() + q_exp <= emin:  # y < 2^emin (includes y == 0)
            flags.append('underflow')

    if n == 0:
        return {"bits": format(s << spos, 'x'), "flags": flags}

    L_y = n.bit_length() - 1 + q_exp
    if L_y < emin:
        e_field = 0
        f = n << (q_exp - (emin - fbits))  # q_exp == emin-fbits here, so f == n
    else:
        e_field = L_y + bias
        sh2 = L_y - fbits - q_exp
        sig = (n >> sh2) if sh2 >= 0 else (n << (-sh2))
        f = sig - F
    bits = (s << spos) | (e_field << fbits) | f
    return {"bits": format(bits, 'x'), "flags": flags}


